// Numbeo の国別・都市別URLを生成するコード

let rowData = {};
let countryJa = "";
let countryEn = "";
let currencyCode = "";
let capital = "";

try {
  const item = $input.first()?.json || {};
  rowData = item.rowData || item;
  countryJa = item.countryJa || rowData["国名（日本語）"] || "";
  countryEn = item.countryEn || rowData["国名（英語）"] || "";
  currencyCode = item.currency || rowData["通貨コード"] || rowData["Numbeo表示通貨"] || "";
  capital = item.capital || rowData["首都（日本語）"] || "";
} catch (e) {}

if (!countryEn && !countryJa) {
  try {
    const merge = $('項目検出・国別マージ').first().json;
    rowData = merge.rowData || {};
    countryJa = merge.countryJa || rowData["国名（日本語）"] || "";
    countryEn = merge.countryEn || rowData["国名（英語）"] || "";
    currencyCode = merge.currency || rowData["通貨コード"] || "";
    capital = merge.capital || rowData["首都（日本語）"] || "";
  } catch (err) {}
}

if (!countryEn && !countryJa) {
  throw new Error("Numbeo用URL生成: 国名が取得できませんでした。");
}

// 主要都市・国名のNumbeoスラッグマッピング（表記ブレ・Numbeo固有URLへの対応）
const numbeoCityMap = {
  "韓国": "Seoul",
  "Republic of Korea": "Seoul",
  "South Korea": "Seoul",
  "コロンビア": "Bogota",
  "Colombia": "Bogota",
  "日本": "Tokyo",
  "Japan": "Tokyo",
  "アメリカ": "Washington-DC",
  "United States": "Washington-DC",
  "イギリス": "London",
  "United Kingdom": "London",
  "フランス": "Paris",
  "France": "Paris",
  "ドイツ": "Berlin",
  "Germany": "Berlin",
  "イタリア": "Rome",
  "Italy": "Rome",
  "カナダ": "Ottawa",
  "Canada": "Ottawa",
  "オーストラリア": "Canberra",
  "Australia": "Canberra",
  "ブラジル": "Brasilia",
  "Brazil": "Brasilia",
  "メキシコ": "Mexico-City",
  "Mexico": "Mexico-City",
  "タイ": "Bangkok",
  "Thailand": "Bangkok",
  "ベトナム": "Hanoi",
  "Vietnam": "Hanoi",
  "インドネシア": "Jakarta",
  "Indonesia": "Jakarta",
  "フィリピン": "Manila",
  "Philippines": "Manila",
  "マレーシア": "Kuala-Lumpur",
  "Malaysia": "Kuala-Lumpur",
  "シンガポール": "Singapore",
  "Singapore": "Singapore",
  "インド": "New-Delhi",
  "India": "New-Delhi",
  "中国": "Beijing",
  "China": "Beijing",
  "台湾": "Taipei",
  "Taiwan": "Taipei",
  "香港": "Hong-Kong",
  "Hong Kong": "Hong-Kong"
};

// スラッグとURLの決定（都市マップにあれば都市URL、なければ国別URL）
let citySlug = numbeoCityMap[countryJa] || numbeoCityMap[countryEn];
let url = "";

if (citySlug) {
  // 主要都市がある場合は都市ページ（例: in/Seoul, in/Bogota）
  url = `https://www.numbeo.com/cost-of-living/in/${citySlug}`;
} else {
  // マップにない国（ブータン等）は国別公式ページ（country_result.jsp?country=Bhutan）
  const countrySlug = countryEn
    .trim()
    .replace(/[^a-zA-Z0-9\s-]/g, '')
    .replace(/\s+/g, '-');
  url = `https://www.numbeo.com/cost-of-living/country_result.jsp?country=${countrySlug}`;
}

// 通貨コードの指定（displayCurrency）
if (currencyCode) {
  const sep = url.includes('?') ? '&' : '?';
  url += `${sep}displayCurrency=${encodeURIComponent(currencyCode)}`;
}

return [{
  json: {
    url,
    countryJa,
    countryEn,
    currencyCode,
    slug: citySlug || countryEn
  }
}];

// Numbeo HTMLデータから最新の日常物価データを抽出するコード

let html = "";
let prevInfo = {};

try {
  const inputJson = $input.first()?.json || {};
  html = inputJson.data || inputJson.html || inputJson.body || "";
  prevInfo = inputJson;
} catch (e) {}

if (!html) {
  try {
    const httpData = $('Numbeoデータ抽出')?.first()?.json || {};
    html = httpData.data || httpData.html || httpData.body || "";
  } catch (err) {}
}

if (!html) {
  throw new Error("Numbeo最新データ抽出: 取得したHTMLデータが空です。");
}

function normalizePriceString(numStr) {
  if (!numStr) return "欠測";
  const hasDot = numStr.includes('.');
  const hasComma = numStr.includes(',');
  let normalized;

  if (hasDot && hasComma) {
    if (numStr.lastIndexOf(',') > numStr.lastIndexOf('.')) {
      normalized = numStr.replace(/\./g, '').replace(',', '.');
    } else {
      normalized = numStr.replace(/,/g, '');
    }
  } else if (hasComma && !hasDot) {
    const parts = numStr.split(',');
    if (parts.length === 2 && parts[1].length <= 2) {
      normalized = numStr.replace(',', '.');
    } else {
      normalized = numStr.replace(/,/g, '');
    }
  } else {
    normalized = numStr.replace(/,/g, '');
  }
  return normalized || "欠測";
}

function extractPrice(htmlContent, keyword) {
  const escaped = keyword.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const trRegex = /<tr[^>]*>([\s\S]*?)<\/tr>/gi;
  let match;

  while ((match = trRegex.exec(htmlContent)) !== null) {
    const trContent = match[1];
    const keyRegex = new RegExp(`<td[^>]*>[^<]*?${escaped}[^<]*?<\\/td>`, 'i');

    if (keyRegex.test(trContent)) {
      const valMatch = trContent.match(/<span class="first_currency">([^<]+?)<\/span>/i);
      if (valMatch && valMatch[1]) {
        let decoded = valMatch[1]
          .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(parseInt(code)))
          .replace(/&amp;/g, '&')
          .replace(/&lt;/g, '<')
          .replace(/&gt;/g, '>');

        let numStr = decoded.replace(/[^\d.,]/g, '').trim();
        numStr = numStr.replace(/^[.,]+|[.,]+$/g, '');
        if (!numStr) continue;
        return normalizePriceString(numStr);
      }
    }
  }
  return "欠測";
}

const actualCurrencyCode = (() => {
  const currencyMatch = html.match(/Currency:\s*([A-Z]{3})/i) || html.match(/Prices in\s*([A-Z]{3})/i);
  if (currencyMatch && currencyMatch[1]) {
    return currencyMatch[1].toUpperCase();
  }
  return prevInfo.currencyCode || "";
})();

const today = new Date().toISOString().split('T')[0];

const extractedPrices = {
  "ビール": extractPrice(html, 'Domestic Draft Beer') !== "欠測" ? extractPrice(html, 'Domestic Draft Beer') : extractPrice(html, 'Domestic Beer'),
  "タバコ": extractPrice(html, 'Cigarettes'),
  "水": extractPrice(html, 'Water'),
  "ガソリン": extractPrice(html, 'Gasoline'),
  "外食": extractPrice(html, 'Meal at an Inexpensive') !== "欠測" ? extractPrice(html, 'Meal at an Inexpensive') : extractPrice(html, 'Meal, Inexpensive'),
  "光熱費": extractPrice(html, 'Basic Utilities') !== "欠測" ? extractPrice(html, 'Basic Utilities') : extractPrice(html, 'Basic (Electricity'),
  "家賃1LDK": extractPrice(html, '1 Bedroom') !== "欠測" ? extractPrice(html, '1 Bedroom') : extractPrice(html, 'Apartment (1 bedroom) in City Centre'),
  "月収": extractPrice(html, 'Average Monthly Net Salary'),
  "出典": "Numbeo",
  "取得日": today,
  "通貨コード": actualCurrencyCode
};

return [{
  json: {
    ...prevInfo,
    日常物価: extractedPrices,
    currencyCode: actualCurrencyCode
  }
}];
